        map.put("guests", r.guests());
        map.put("ratePlan", r.ratePlan());
        map.put("nights", r.nights());
        map.put("subtotal", r.subtotal());
        map.put("discount", r.discount());
        map.put("total", r.total());
        map.put("status", r.status());
