package com.pousadamarealta;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.pousadamarealta.document.DocumentService;
import com.pousadamarealta.repository.MessageRepository;
import com.pousadamarealta.repository.ReservationRepository;
import com.pousadamarealta.repository.RoomRepository;
import com.pousadamarealta.service.ReportService;
import com.pousadamarealta.service.ReservationService;
import com.pousadamarealta.web.ApiController;
import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import io.javalin.Javalin;
import io.javalin.json.JavalinJackson;
import org.junit.jupiter.api.*;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

class ReservationFlowIT {
    private static Javalin app;
    private static int port = 7071;
    private static HttpClient client;
    private static ObjectMapper mapper;

    @BeforeAll
    static void setup() {
        HikariDataSource dataSource = createTestDataSource();

        RoomRepository roomRepository = new RoomRepository(dataSource);
        ReservationRepository reservationRepository = new ReservationRepository(dataSource);
        MessageRepository messageRepository = new MessageRepository(dataSource);

        roomRepository.initialize();
        reservationRepository.initialize();
        messageRepository.initialize();

        DocumentService documentService = new DocumentService();
        ReservationService reservationService = new ReservationService(
            reservationRepository, roomRepository, messageRepository, documentService);
        ReportService reportService = new ReportService(reservationRepository, roomRepository);

        ApiController apiController = new ApiController(
            roomRepository, messageRepository, reservationService, reportService);

        mapper = new ObjectMapper().registerModule(new JavaTimeModule());

        app = Javalin.create(config -> {
            config.jsonMapper(new JavalinJackson(mapper));
        }).start(port);

        apiController.registerRoutes(app);

        client = HttpClient.newHttpClient();
    }

    @AfterAll
    static void teardown() {
        if (app != null) {
            app.stop();
        }
    }

    @Test
    void shouldCompleteFullReservationFlow() throws Exception {
        String createBody = """
            {
                "roomNumber": 101,
                "guestName": "João Silva",
                "guestEmail": "joao@example.com",
                "guestCpf": "123.456.789-00",
                "checkIn": "2027-07-10",
                "checkOut": "2027-07-12",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
            """;

        HttpResponse<String> createResponse = post("/reservations", createBody);
        assertThat(createResponse.statusCode()).isEqualTo(201);

        Map<String, Object> reservation = mapper.readValue(createResponse.body(), Map.class);
        assertThat(reservation.get("status")).isEqualTo("PENDING");
        assertThat(reservation.get("nights")).isEqualTo(2);
        assertThat(reservation.get("amountPaid")).isEqualTo(0.0);

        int id = (Integer) reservation.get("id");

        HttpResponse<String> confirmResponse = post("/reservations/" + id + "/confirmation", "");
        assertThat(confirmResponse.statusCode()).isEqualTo(200);
        Map<String, Object> confirmed = mapper.readValue(confirmResponse.body(), Map.class);
        assertThat(confirmed.get("status")).isEqualTo("CONFIRMED");
        assertThat(((Number) confirmed.get("amountPaid")).doubleValue()).isGreaterThan(0);

        HttpResponse<String> messagesResponse = get("/messages");
        assertThat(messagesResponse.statusCode()).isEqualTo(200);
        assertThat(messagesResponse.body()).contains("Reserva confirmada");

        HttpResponse<String> checkInResponse = post("/reservations/" + id + "/check-in", "");
        assertThat(checkInResponse.statusCode()).isEqualTo(200);
        Map<String, Object> checkedIn = mapper.readValue(checkInResponse.body(), Map.class);
        assertThat(checkedIn.get("status")).isEqualTo("CHECKED_IN");

        HttpResponse<String> checkOutResponse = post("/reservations/" + id + "/check-out", "");
        assertThat(checkOutResponse.statusCode()).isEqualTo(200);
        Map<String, Object> document = mapper.readValue(checkOutResponse.body(), Map.class);
        assertThat(document.get("text")).asString().contains("Comprovante de reserva");
    }

    @Test
    void shouldGenerateCorporateDocument() throws Exception {
        String createBody = """
            {
                "roomNumber": 201,
                "guestName": "Ana Souza",
                "guestEmail": "ana@example.com",
                "companyCnpj": "12.345.678/0001-90",
                "companyName": "Tecnosul Ltda",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
            """;

        HttpResponse<String> createResponse = post("/reservations", createBody);
        assertThat(createResponse.statusCode()).isEqualTo(201);

        Map<String, Object> reservation = mapper.readValue(createResponse.body(), Map.class);
        int id = (Integer) reservation.get("id");

        post("/reservations/" + id + "/confirmation", "");

        HttpResponse<String> documentResponse = get("/reservations/" + id + "/document");
        assertThat(documentResponse.statusCode()).isEqualTo(200);
        Map<String, Object> document = mapper.readValue(documentResponse.body(), Map.class);
        assertThat(document.get("text")).asString().contains("Fatura de hospedagem");
        assertThat(document.get("text")).asString().contains("ISS retido");
    }

    @Test
    void shouldGenerateForeignDocument() throws Exception {
        String createBody = """
            {
                "roomNumber": 301,
                "guestName": "John Smith",
                "guestEmail": "john@example.com",
                "guestPassport": "X1234567",
                "guestCountry": "United Kingdom",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
            """;

        HttpResponse<String> createResponse = post("/reservations", createBody);
        assertThat(createResponse.statusCode()).isEqualTo(201);

        Map<String, Object> reservation = mapper.readValue(createResponse.body(), Map.class);
        int id = (Integer) reservation.get("id");

        post("/reservations/" + id + "/confirmation", "");

        HttpResponse<String> documentResponse = get("/reservations/" + id + "/document");
        assertThat(documentResponse.statusCode()).isEqualTo(200);
        Map<String, Object> document = mapper.readValue(documentResponse.body(), Map.class);
        assertThat(document.get("text")).asString().contains("Booking receipt");
        assertThat(document.get("text")).asString().contains("BRL");
    }

    @Test
    void shouldRejectRoomUnavailable() throws Exception {
        String createBody1 = """
            {
                "roomNumber": 102,
                "guestName": "Maria Santos",
                "guestEmail": "maria@example.com",
                "guestCpf": "111.222.333-44",
                "checkIn": "2027-08-01",
                "checkOut": "2027-08-05",
                "guests": 1,
                "ratePlan": "STANDARD"
            }
            """;

        HttpResponse<String> createResponse1 = post("/reservations", createBody1);
        assertThat(createResponse1.statusCode()).isEqualTo(201);
        Map<String, Object> res1 = mapper.readValue(createResponse1.body(), Map.class);
